446	bool MergeTreeIndexGranuleText::hasAnyQueryTokens(const TextSearchQuery & query) const
447	{
448	    if (!current_range.has_value())
449	    {
450	        return std::ranges::any_of(query.tokens, [this](const auto & token)
451	        {
452	            return remaining_tokens.contains(token);
453	        });
454	    }
455	
456	    PostingList range_posting;
457	    range_posting.addRangeClosed(static_cast<UInt32>(current_range->begin), static_cast<UInt32>(current_range->end));
458	
459	    for (const auto & token : query.tokens)
460	    {
461	        auto it = remaining_tokens.find(token);
462	        if (it == remaining_tokens.end())
463	            continue;
464	
465	        bool has_any_range = std::ranges::any_of(it->second.ranges, [this](const auto & range)
466	        {
467	            return current_range->intersects(range);
468	        });
469	
470	        if (!has_any_range)
471	            continue;
472	
473	        /// We read postings only for tokens that has one block.
474	        /// Otherwise, assume that the token is not useful
475	        /// for filtering and is present in all granules.
476	        auto postings = getPostingsForRareToken(token);
477	        if (!postings)
478	            return true;
479	
480	        auto intersection = *postings & range_posting;
481	        if (!intersection.isEmpty())
482	            return true;
483	    }
484	
485	    return false;
486	}
