503	        });
504	    }
505	
506	    PostingList intersection;
507	    intersection.addRangeClosed(static_cast<UInt32>(current_range->begin), static_cast<UInt32>(current_range->end));
508	
509	    for (const auto & token : query.tokens)
510	    {
511	        auto it = remaining_tokens.find(token);
512	        if (it == remaining_tokens.end())
513	            return false;
514	
515	        bool has_any_range = std::ranges::any_of(it->second.ranges, [this](const auto & range)
516	        {
517	            return current_range->intersects(range);
518	        });
519	
520	        if (!has_any_range)
521	            return false;
522	
523	        /// We read postings only for tokens that has one block.
524	        /// Otherwise, assume that the token is not useful
525	        /// for filtering and is present in all granules.
526	        if (auto postings = getPostingsForRareToken(token))
527	        {
