    /// When the `mapValues(map)` index is used for `map['key'] IN (...)`, an empty string among the
    /// searched values makes the index unusable: `map['key']` evaluates to the default empty string
    /// when the key is absent, so the condition may hold for rows whose map does not contain the
    /// empty value at all. In that case we cannot use the index to skip granules.
    if (set_key_is_map_values_element)
    {
        for (size_t row = 0; row < total_row_count; ++row)
        {
            if (set_column.getDataAt(row).empty())
                return false;
        }
    }

    for (size_t row = 0; row < total_row_count; ++row)
    {
        auto ref = set_column.getDataAt(row);

